SELECT id, name, email, country, city, segment, signup_date, is_active, credit_limit, age, NTILE(3) OVER (PARTITION BY city ORDER BY credit_limit DESC, id ASC) AS credit_limit_bucket, ROUND(credit_limit / SUM(credit_limit) OVER (PARTITION BY city), 4) AS credit_limit_share, LAG(age, 2) OVER (PARTITION BY city ORDER BY signup_date ASC, id ASC) AS prev_age, NTILE(10) OVER (PARTITION BY country, city ORDER BY age ASC, id ASC) AS age_bucket, SUM(credit_limit) OVER (ORDER BY signup_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_credit_limit FROM customers
